drop table if exists gct.gcttb900_teste;

create table gct.gcttb900_teste (
  co_solicitacao varchar(30)
);


update gct.gcttb005_solicitacao set ic_pendente_atualizacao='N' where ic_pendente_atualizacao='S';

--
--
--
-- update gct.gcttb005_solicitacao set ic_pendente_atualizacao='S', dh_processamento=null where co_solicitacao in (
--   select co_solicitacao from gct.gcttb900_teste
-- );

--
--
--
update 
  gct.gcttb005_solicitacao 
set 
  ic_pendente_atualizacao='S', 
  ic_bef='N', 
  dh_processamento=null ,
  nu_rubrica = null, 
  co_rubrica = null
where 
  co_solicitacao in (
  select 
    distinct s.co_solicitacao
  from 
    gct.gcttb005_solicitacao s
  where 
    (
      s.dh_prevista::date > '2025-09-20'
      or s.dh_efetiva > '2025-09-20'
    )
);
